/**
 * ContextMenuComponent
 *
 * A child component (must live inside a <Graphin> tree) that renders a
 * floating, interactive panel anchored near the node the user clicked.
 *
 * Behaviour:
 *  - Opens on `node:click`.
 *  - Stays open until:
 *      (a) the user clicks outside the panel, or
 *      (b) the built-in ✕ close button is pressed.
 *  - An `onClose` callback is forwarded to the content card so custom
 *    cards can close the panel programmatically.
 *  - The panel passes `GraphinNodeEventContext` (nodeId, nodeData, x, y)
 *    as extra props to the content card.
 */
import React, {useState, useEffect, useRef, useCallback} from "react";
import {useGraphin} from "@antv/graphin";
import type {IPointerEvent} from "@antv/g6";
import type {DisplayObject} from "@antv/g";
import {Target} from "@antv/g6/lib/types";
import {Card} from "@pihanga2/core";
import type {
  GraphinContextMenu,
  GraphinNodeEventContext,
} from "./graphin.types";

// ---------------------------------------------------------------------------
// Public context type
// ---------------------------------------------------------------------------

/**
 * Context forwarded to the content card as props.
 * Consumers can import this type to type their card props:
 *
 * ```ts
 * type MyMenuProps = ContextMenuContext & { ... }
 * ```
 */
export type ContextMenuContext<T = Record<string, unknown>> = {
  /** Whether this panel was triggered from an edge (vs node) */
  isEdge?: boolean;
  /** The G6 element id */
  elementID?: string;
  /** The element's raw `data` bag */
  elementData?: T;
  /**
   * Call this to close the context menu panel from within the content card.
   */
  onClose?: () => void;
};

// ---------------------------------------------------------------------------
// Internal state
// ---------------------------------------------------------------------------

type ContextMenuState = ContextMenuContext & {
  visible: boolean;
  x: number;
  y: number;
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

/** Resolve offset prop → [ox, oy] in pixels. */
function resolveOffset(
  offset: number | [number, number] | undefined,
): [number, number] {
  if (offset === undefined) return [4, 4];
  if (Array.isArray(offset)) return offset;
  return [offset, offset];
}

/**
 * Compute the pointer position in **CSS pixels relative to the G6 container
 * element** so that `position:absolute` overlays land at the click point
 * regardless of zoom / pan / page scroll / container offset.
 */
function getContainerXY(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  graph: any,
  evt: IPointerEvent<DisplayObject & Target>,
): [number, number] {
  try {
    const container: HTMLElement | undefined =
      graph?.container ??
      graph?.canvas?.getConfig?.()?.container ??
      graph?.getContainer?.();
    if (container) {
      const rect = container.getBoundingClientRect();
      const clientEvt = evt as unknown as {client?: {x: number; y: number}};
      const cx = clientEvt.client?.x ?? rect.left;
      const cy = clientEvt.client?.y ?? rect.top;
      return [cx - rect.left, cy - rect.top];
    }
  } catch {
    // fall through
  }
  const vp = (evt as unknown as {viewport?: {x: number; y: number}}).viewport;
  if (vp) return [vp.x, vp.y];
  return [evt.canvas?.x ?? evt.x, evt.canvas?.y ?? evt.y];
}

export function ContextMenuComponent(props: {
  contentCards: GraphinContextMenu;
  parentCard: string;
  onOpen?: (ctx: GraphinNodeEventContext) => void;
  onClose?: (ctx: GraphinNodeEventContext) => void;
}): React.ReactNode {
  const {contentCards, parentCard, onOpen, onClose} = props;
  const [ox, oy] = resolveOffset(contentCards.offset);
  const {graph, isReady} = useGraphin();

  const [menu, setMenu] = useState<ContextMenuState>({
    visible: false,
    x: 0,
    y: 0,
  });

  const containerRef = useRef<HTMLDivElement>(null);
  const isOpeningRef = useRef(false);
  // Keep Pihanga callbacks in refs so closures always call the latest version
  const onOpenRef = useRef(onOpen);
  const onCloseRef = useRef(onClose);
  onOpenRef.current = onOpen;
  onCloseRef.current = onClose;
  // Store last context so onClose can forward it
  const lastCtxRef = useRef<GraphinNodeEventContext | null>(null);

  const handleClose = useCallback(() => {
    const ctx = lastCtxRef.current ?? {nodeId: "", x: 0, y: 0};
    setMenu((prev) => ({...prev, visible: false}));
    onCloseRef.current?.(ctx);
  }, []);

  // ── G6 node click → open / update panel ───────────────────────────────
  useEffect(() => {
    if (!isReady || !graph) return;

    const handleNodeClick = (evt: IPointerEvent<DisplayObject & Target>) => {
      const nodeId = (evt.target as {id?: string})?.id;
      if (!nodeId) return;

      isOpeningRef.current = true;
      setTimeout(() => {
        isOpeningRef.current = false;
      }, 0);

      const [px, py] = getContainerXY(graph, evt);
      let nodeData: Record<string, unknown> | undefined;
      try {
        nodeData = graph.getNodeData(nodeId)?.data as
          | Record<string, unknown>
          | undefined;
      } catch {
        // noop
      }
      const ctx: GraphinNodeEventContext = {nodeId, nodeData, x: px, y: py};
      lastCtxRef.current = ctx;
      setMenu({
        visible: true,
        x: px,
        y: py,
        isEdge: false,
        elementID: nodeId,
        elementData: nodeData,
      });
      onOpenRef.current?.(ctx);
    };

    graph.on("node:click", handleNodeClick);
    return () => {
      graph.off("node:click", handleNodeClick);
    };
  }, [graph, isReady]);

  // ── Outside-click → dismiss ────────────────────────────────────────────
  useEffect(() => {
    if (!menu.visible) return;

    const handleOutsideClick = (e: MouseEvent) => {
      // Ignore the click that opened this menu
      if (isOpeningRef.current) return;

      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
        handleClose();
      }
    };

    // Defer by one tick so the click that opened the menu isn't caught
    const timer = setTimeout(() => {
      document.addEventListener("mousedown", handleOutsideClick);
    }, 0);

    return () => {
      clearTimeout(timer);
      document.removeEventListener("mousedown", handleOutsideClick);
    };
  }, [menu.visible, handleClose]);

  // ── Nothing to render ─────────────────────────────────────────────────
  if (!contentCards.node) return null;
  if (!menu.visible) return null;

  const {visible: _v, x, y, ...contextProps} = menu;

  return (
    <div
      ref={containerRef}
      style={{
        position: "absolute",
        left: x + ox,
        top: y + oy,
        zIndex: 1000,
        // Panel is fully interactive
        pointerEvents: "auto",
      }}
      // Prevent clicks inside the panel from bubbling to the outside-click handler
      onMouseDown={(e) => e.stopPropagation()}
    >
      {/* Content card — responsible for its own chrome (close button, etc.) */}
      <Card
        cardName={contentCards.node}
        parentCard={parentCard}
        {...contextProps}
        onClose={handleClose}
      />
    </div>
  );
}

/**
 * GraphinEventDispatcher
 *
 * A renderless child component (must live inside a <Graphin> tree) that
 * attaches G6 node-level event listeners and bridges them to Pihanga
 * action dispatchers extracted from the parent card's props.
 *
 * Using a child component + useGraphin() keeps the listeners in sync with
 * the graph instance without requiring re-registration on every parent
 * render: the ref pattern ensures handlers always see fresh closures.
 */
import {useEffect, useRef} from "react";
import {useGraphin} from "@antv/graphin";
import type {IPointerEvent} from "@antv/g6";
import type {DisplayObject} from "@antv/g";
import {Target} from "@antv/g6/lib/types";
import type {GraphinNodeEventContext} from "./graphin.types";

export type GraphinEventDispatcherProps = {
  onNodeHovered?: (ctx: GraphinNodeEventContext) => void;
  onNodeHoverEnd?: (ctx: GraphinNodeEventContext) => void;
  onNodeClicked?: (ctx: GraphinNodeEventContext) => void;
  onNodeDblClicked?: (ctx: GraphinNodeEventContext) => void;
};

export function GraphinEventDispatcher(
  props: GraphinEventDispatcherProps,
): null {
  const {graph, isReady} = useGraphin();

  // Use a ref so G6 listeners always call the latest handlers without
  // needing to be torn down and re-registered on every render.
  const handlersRef = useRef(props);
  handlersRef.current = props;

  useEffect(() => {
    if (!isReady || !graph) return;

    const buildCtx = (
      evt: IPointerEvent<DisplayObject & Target>,
    ): GraphinNodeEventContext | null => {
      const nodeId = (evt.target as {id?: string})?.id;
      if (!nodeId) return null;
      try {
        const nodeData = graph.getNodeData(nodeId);
        return {
          nodeId,
          nodeData: nodeData?.data as Record<string, unknown> | undefined,
          x: evt.canvas?.x ?? evt.x,
          y: evt.canvas?.y ?? evt.y,
        };
      } catch {
        // node data may not be accessible (e.g. edge label click)
        return {
          nodeId,
          x: evt.canvas?.x ?? evt.x,
          y: evt.canvas?.y ?? evt.y,
        };
      }
    };

    const handleNodePointerEnter = (
      evt: IPointerEvent<DisplayObject & Target>,
    ) => {
      const ctx = buildCtx(evt);
      if (ctx) handlersRef.current.onNodeHovered?.(ctx);
    };

    const handleNodePointerLeave = (
      evt: IPointerEvent<DisplayObject & Target>,
    ) => {
      const ctx = buildCtx(evt);
      if (ctx) handlersRef.current.onNodeHoverEnd?.(ctx);
    };

    const handleNodeClick = (evt: IPointerEvent<DisplayObject & Target>) => {
      const ctx = buildCtx(evt);
      if (ctx) handlersRef.current.onNodeClicked?.(ctx);
    };

    const handleNodeDblClick = (evt: IPointerEvent<DisplayObject & Target>) => {
      const ctx = buildCtx(evt);
      if (ctx) handlersRef.current.onNodeDblClicked?.(ctx);
    };

    graph.on("node:pointerenter", handleNodePointerEnter);
    graph.on("node:pointerleave", handleNodePointerLeave);
    graph.on("node:click", handleNodeClick);
    graph.on("node:dblclick", handleNodeDblClick);

    return () => {
      graph.off("node:pointerenter", handleNodePointerEnter);
      graph.off("node:pointerleave", handleNodePointerLeave);
      graph.off("node:click", handleNodeClick);
      graph.off("node:dblclick", handleNodeDblClick);
    };
  }, [graph, isReady]);

  return null;
}

import React, {useEffect, useRef} from "react";
import {PiCardProps} from "@pihanga2/core";
import {Graphin, useGraphin} from "@antv/graphin";
import {type GraphOptions} from "@antv/g6";

import {
  type GraphinEvents,
  type GraphinNodeStyleMap,
  type GraphinProps,
} from "./graphin.types";
import clsx from "clsx";
import {cloneDeep, merge} from "lodash";
import {TooltipComponent} from "./tooltip.component";
import {ContextMenuComponent} from "./contextMenu.component";
import {GraphinEventDispatcher} from "./eventDispatcher.component";
import {GraphinOpHandler} from "./graphinOpHandler.component";

/**
 * Renderless child (must live inside a <Graphin> tree).
 * Keeps `nodeStylesRef` in sync with the `nodeStyles` prop and calls
 * graph.draw() to re-apply styles without re-running the layout.
 */
function NodeStyleWatcher({
  nodeStyles,
  nodeStylesRef,
}: {
  nodeStyles?: GraphinNodeStyleMap;
  nodeStylesRef: React.MutableRefObject<GraphinNodeStyleMap>;
}): null {
  const {graph, isReady} = useGraphin();

  useEffect(() => {
    nodeStylesRef.current = nodeStyles ?? {};
    if (isReady && graph) {
      void graph.draw();
    }
  }, [nodeStyles, graph, isReady, nodeStylesRef]);

  return null;
}

/**
 * Renderless child (must live inside a <Graphin> tree).
 * Calls graph.zoomTo() imperatively whenever `zoomLevel` changes so that
 * zoom updates work after initial mount — options.zoom is only read once.
 */
function ZoomController({zoomLevel}: {zoomLevel?: number}): null {
  const {graph, isReady} = useGraphin();

  useEffect(() => {
    if (!isReady || !graph || zoomLevel === undefined) return;
    graph.zoomTo(zoomLevel, {duration: 300});
  }, [graph, isReady, zoomLevel]);

  return null;
}

export const GraphinComponent = (
  props: PiCardProps<GraphinProps, GraphinEvents>,
): React.ReactNode => {
  const {
    cardName,
    data,
    options,
    layout,
    suppressZoom,
    suppressPan,
    suppressDrag,
    zoomLevel,
    directed,
    tooltip,
    contextMenu,
    style,
    className,
    _cls,
    onNodeHovered,
    onNodeHoverEnd,
    onNodeClicked,
    onNodeDblClicked,
    onTooltipOpen,
    onTooltipClose,
    onContextMenuOpen,
    onContextMenuClose,
    nodeStyles,
    nodeStyleKey,
  } = props;

  // ── nodeStyles ref ───────────────────────────────────────────────────────
  // Kept in a ref so G6 style functions can always read the LATEST map value
  // without rebuilding mergedOptions (which would re-run the layout).
  // Updated by NodeStyleWatcher (on prop change) and by GraphinOpHandler
  // (on OP action), both of which call graph.draw() to trigger a re-render.
  const nodeStylesRef = useRef<GraphinNodeStyleMap>(nodeStyles ?? {});
  const nodeStyleKeyRef = useRef(nodeStyleKey ?? "style");
  // Keep refs in sync on every render so their values are always fresh.
  nodeStylesRef.current = nodeStyles ?? {};
  nodeStyleKeyRef.current = nodeStyleKey ?? "style";

  const _style = {
    display: "flex",
    width: "100%",
    // Prevent the G6 WebGL/Canvas element from bleeding outside its container
    // and painting over sibling elements (controls panel, JSON viewer, etc.).
    overflow: "hidden",
    position: "relative" as const,
    ...style?.root,
  };

  // ── Build options (memoised) ────────────────────────────────────────────
  // IMPORTANT: `mergedOptions` must NOT be recreated on every render.
  // If a new object reference is passed to <Graphin options={...}> on each
  // render G6 calls graph.setOptions() / graph.layout() which snaps every
  // node back to its layout position, undoing any manual drag.
  const mergedOptions = React.useMemo<GraphOptions>(() => {
    const defOptions: GraphOptions = {
      data,
      autoResize: true,
      node: {
        style: {
          labelText: (d) => {
            return (d.data?.displayName || d.id) as string;
          },
          lod: {
            0: {labelFontSize: 10},
            1: {labelFontSize: 12},
            2: {labelFontSize: 6},
          },
        },
      },
      layout: {
        type: "force-atlas2",
        preventOverlap: true,
        kr: 20,
        // Run synchronously in one pass then stop so dragged nodes stay put.
        animation: false,
      },
      behaviors: [
        "drag-canvas",
        "drag-element",
        {
          type: "auto-adapt-label",
          enableAnimation: true,
          throttle: 100,
          padding: 0,
        },
        {
          type: "zoom-canvas",
          id: "zoom-canvas-1",
          fixSelectedItems: {fixLabel: true},
        },
      ],
      animation: true,
    };

    const merged = merge(cloneDeep(defOptions), options);

    // ── layout shorthand ──────────────────────────────────────────────────
    if (layout) {
      const existing = merged.layout;
      if (
        existing &&
        !Array.isArray(existing) &&
        typeof existing === "object"
      ) {
        (existing as Record<string, unknown>).type = layout;
      } else {
        merged.layout = {type: layout};
      }
    }

    // ── suppressZoom ──────────────────────────────────────────────────────
    if (suppressZoom && Array.isArray(merged.behaviors)) {
      merged.behaviors = merged.behaviors.filter((b) => {
        if (typeof b === "string") return b !== "zoom-canvas";
        if (typeof b === "object" && b !== null)
          return (b as Record<string, unknown>).type !== "zoom-canvas";
        return true;
      });
    }

    // ── suppressPan ───────────────────────────────────────────────────────
    if (suppressPan && Array.isArray(merged.behaviors)) {
      merged.behaviors = merged.behaviors.filter((b) => {
        if (typeof b === "string") return b !== "drag-canvas";
        if (typeof b === "object" && b !== null)
          return (b as Record<string, unknown>).type !== "drag-canvas";
        return true;
      });
    }

    // ── suppressDrag ──────────────────────────────────────────────────────
    if (suppressDrag && Array.isArray(merged.behaviors)) {
      merged.behaviors = merged.behaviors.filter((b) => {
        if (typeof b === "string") return b !== "drag-element";
        if (typeof b === "object" && b !== null)
          return (b as Record<string, unknown>).type !== "drag-element";
        return true;
      });
    }

    // ── zoomLevel ─────────────────────────────────────────────────────────
    // G6's autoFit ('view') runs after layout and overrides options.zoom.
    // Disable it when an explicit zoom is requested so the value is respected.
    // Range: [0.02, 16] — 1 = 100 %, 0.5 = 50 % (zoom out), 2 = 200 % (zoom in).
    if (zoomLevel !== undefined) {
      merged.zoom = zoomLevel;
      if (!merged.autoFit) {
        // only override when the caller hasn't set autoFit themselves
        merged.autoFit = undefined; // disables the default 'view' autoFit
      }
    }

    // ── directed ──────────────────────────────────────────────────────────
    if (directed) {
      merged.edge = merge(merged.edge ?? {}, {style: {endArrow: true}});
    }

    // ── nodeStyles ─────────────────────────────────────────────────────────
    // Build G6 style functions from the serialisable nodeStyles map.
    // The functions close over nodeStylesRef and nodeStyleKeyRef (both stable
    // refs) so G6 always reads the LATEST map on every draw — OP actions and
    // prop changes update the refs and call graph.draw() independently.
    if (nodeStyles !== undefined) {
      const getSpec = (d: {id?: string; data?: Record<string, unknown>}) => {
        const key = nodeStyleKeyRef.current;
        const name = d.data?.[key] as string | undefined;
        return name ? nodeStylesRef.current[name] : undefined;
      };

      const baseStyle = (merged.node?.style ?? {}) as Record<string, unknown>;
      merged.node = {
        ...merged.node,
        // Per-node shape driven by the style map
        type: (d: {id?: string; data?: Record<string, unknown>}) =>
          getSpec(d)?.type ?? "circle",
        style: {
          // Preserve defaults (labelText, lod) from defOptions
          ...baseStyle,
          fill: (d: {id?: string; data?: Record<string, unknown>}) =>
            getSpec(d)?.fill ?? "#4793AF",
          stroke: (d: {id?: string; data?: Record<string, unknown>}) =>
            getSpec(d)?.stroke ?? "#d2dde8",
          lineWidth: (d: {id?: string; data?: Record<string, unknown>}) =>
            getSpec(d)?.lineWidth ?? 1,
          size: (d: {id?: string; data?: Record<string, unknown>}) =>
            getSpec(d)?.size ?? 24,
          opacity: (d: {id?: string; data?: Record<string, unknown>}) =>
            getSpec(d)?.opacity ?? 1,
          labelFill: (d: {id?: string; data?: Record<string, unknown>}) =>
            getSpec(d)?.labelFill ?? "#000000",
          labelFontSize: (d: {id?: string; data?: Record<string, unknown>}) =>
            getSpec(d)?.labelFontSize ?? 12,
        },
      };
    }

    return merged;
    // NOTE: nodeStyles is intentionally excluded from deps.
    // Style functions close over nodeStylesRef (always current) so G6 sees
    // the latest values without rebuilding the options / re-running the layout.
    // NodeStyleWatcher (below) triggers graph.draw() when the prop changes.
    // nodeStyleKey is intentionally included as a change-trigger even though
    // it is not referenced directly in the callback body.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    data,
    options,
    layout,
    suppressZoom,
    suppressPan,
    suppressDrag,
    zoomLevel,
    directed,
    nodeStyles, // include so that the style functions are installed when
    nodeStyleKey, // nodeStyles is first provided (or key changes)
  ]);

  return (
    <div
      style={_style}
      className={clsx(_cls("root"), className)}
      data-pihanga={cardName}
    >
      <Graphin options={mergedOptions} style={{width: "inherit"}}>
        {/* Hover tooltip — pointer-events: none floating card */}
        {tooltip && (
          <TooltipComponent
            contentCards={tooltip}
            parentCard={cardName}
            onOpen={onTooltipOpen}
            onClose={onTooltipClose}
          />
        )}

        {/* Context panel — interactive, click-to-open, outside-click-to-close */}
        {contextMenu && (
          <ContextMenuComponent
            contentCards={contextMenu}
            parentCard={cardName}
            onOpen={onContextMenuOpen}
            onClose={onContextMenuClose}
          />
        )}

        {/* Keeps nodeStylesRef in sync with prop; triggers graph.draw() on change */}
        {nodeStyles !== undefined && (
          <NodeStyleWatcher
            nodeStyles={nodeStyles}
            nodeStylesRef={nodeStylesRef}
          />
        )}

        {/* Applies explicit zoom imperatively — options.zoom is only read on mount */}
        <ZoomController zoomLevel={zoomLevel} />

        {/* Handles OP actions (setNodeStyles, clearNodeStyles, zoomToNode, updateNodeStyleMap) */}
        <GraphinOpHandler
          cardName={cardName}
          nodeStylesRef={nodeStylesRef}
          nodeStyleKeyRef={nodeStyleKeyRef}
        />

        {/* Bridges G6 node events to Pihanga action dispatchers */}
        <GraphinEventDispatcher
          onNodeHovered={onNodeHovered}
          onNodeHoverEnd={onNodeHoverEnd}
          onNodeClicked={onNodeClicked}
          onNodeDblClicked={onNodeDblClicked}
        />
      </Graphin>
    </div>
  );
};

/**
 * Tiny card registrations used exclusively by the Graphin playground examples.
 *
 * These are NOT part of the card library — they are demo-only components
 * showing how tooltip / context-menu content cards receive node context from
 * the Graphin card.  Imported (for side effects) by graphin.example.ts.
 */
import React from "react";
import {registerCardComponent} from "@pihanga2/core";
import type {TooltipContext} from "./tooltip.component";
import type {ContextMenuContext} from "./contextMenu.component";

// ---------------------------------------------------------------------------
// Demo tooltip card
// ---------------------------------------------------------------------------

type DemoTooltipProps = TooltipContext & {
  cardName: string;
  parentCard: string;
};

/**
 * Minimal tooltip content card for the playground demo.
 *
 * In a real app you'd replace this with any PiCard (a Typography, a Stack
 * of fields, even a DataTable) — the same `elementID` and `elementData`
 * context props are always forwarded to whatever card you point `tooltip.node`
 * at.
 */
function DemoTooltipCard(props: DemoTooltipProps): React.ReactNode {
  const displayName =
    (props.elementData?.displayName as string | undefined) ?? props.elementID;
  const extraFields = Object.entries(props.elementData ?? {}).filter(
    ([k]) => k !== "displayName",
  );

  return (
    <div style={{minWidth: 160}}>
      <p
        style={{
          margin: 0,
          fontWeight: 600,
          fontSize: 13,
          lineHeight: 1.4,
        }}
      >
        {displayName}
      </p>
      {extraFields.map(([k, v]) => (
        <p key={k} style={{margin: "3px 0 0", fontSize: 11, opacity: 0.65}}>
          {k}: {String(v)}
        </p>
      ))}
    </div>
  );
}

registerCardComponent({
  name: "pg/graphin/demo-tooltip",
  component: DemoTooltipCard as Parameters<
    typeof registerCardComponent
  >[0]["component"],
});

// ---------------------------------------------------------------------------
// Demo context-menu card
// ---------------------------------------------------------------------------

type DemoContextMenuProps = ContextMenuContext & {
  cardName: string;
  parentCard: string;
};

/**
 * Minimal context-panel content card for the playground demo.
 *
 * The ContextMenuComponent already wraps it in a panel with a ✕ close button.
 * The `onClose` callback is forwarded here so custom cards can also dismiss
 * the panel programmatically (e.g. after a "Delete node" action).
 *
 * In a real app you'd render action buttons, a detailed form, or even a full
 * PiCard layout — whatever you need the panel to show for the clicked node.
 */
function DemoContextMenuCard(props: DemoContextMenuProps): React.ReactNode {
  const displayName =
    (props.elementData?.displayName as string | undefined) ?? props.elementID;
  const entries = Object.entries(props.elementData ?? {});

  return (
    <div style={{minWidth: 200}}>
      {/* Node name */}
      <p
        style={{
          margin: 0,
          fontWeight: 600,
          fontSize: 14,
          lineHeight: 1.4,
        }}
      >
        {displayName}
      </p>

      {/* ID */}
      {props.elementID && (
        <p style={{margin: "4px 0 0", fontSize: 11, opacity: 0.6}}>
          id: {props.elementID}
        </p>
      )}

      {/* All data fields */}
      {entries.length > 0 && (
        <table
          style={{
            marginTop: 10,
            width: "100%",
            borderCollapse: "collapse",
            fontSize: 12,
          }}
        >
          <tbody>
            {entries.map(([k, v]) => (
              <tr key={k}>
                <td
                  style={{
                    padding: "2px 8px 2px 0",
                    opacity: 0.65,
                    whiteSpace: "nowrap",
                    verticalAlign: "top",
                  }}
                >
                  {k}
                </td>
                <td style={{padding: "2px 0", fontWeight: 500}}>{String(v)}</td>
              </tr>
            ))}
